    protected static function cat(string $slug, string $icon, string $en, string $ar, string $descEn, string $descAr, array $courses): array
    {
        $mapped = [];
        foreach ($courses as $c) {
            [$cSlug, $titleEn, $titleAr, $subEn, $subAr, $level, $price] = $c;
            $featured = $c[7] ?? false;
            $mapped[] = [
                'slug' => $cSlug,
                'title_en' => $titleEn,
                'title_ar' => $titleAr,
                'subtitle_en' => $subEn,
                'subtitle_ar' => $subAr,
                'description_en' => "A practical {$titleEn} course for real marketplace learners. Includes guided lessons, demos, and project-oriented practice.",
                'description_ar' => "دورة عملية في {$titleAr} للمتعلمين الجادين. تتضمن دروسًا موجهة وعروضًا وتمارين قائمة على المشاريع.",
                'level' => $level,
                'price' => $price,
                'featured' => (bool) $featured,
            ];
        }

        return [
            'slug' => $slug,
            'icon' => $icon,
            'en' => $en,
            'ar' => $ar,
            'desc_en' => $descEn,
            'desc_ar' => $descAr,
            'courses' => $mapped,
        ];
    }
